sap.ui.define([
  "sap/m/Text",
  "sap/ui/core/HTML",
  "sap/base/security/encodeXML"
], function (Text, HTML, encodeXML) {
  "use strict";

  const userInput = "<img src=x onerror=\"alert('XSS')\">";

  // safe: the Text control escapes it, the user sees the characters
  new Text({ text: userInput });

  // UNSAFE: raw HTML, the browser runs the onerror code
  // new HTML({ content: "<div>" + userInput + "</div>" });

  // safe: encode before putting it into HTML, or sanitize the HTML
  new HTML({ content: "<div>" + encodeXML(userInput) + "</div>" });
  new HTML({ content: "<div>" + userInput + "</div>", sanitizeContent: true });
});

sap.ui.define([
  "sap/base/security/encodeURLParameters",
  "sap/base/security/URLListValidator"
], function (encodeURLParameters, URLListValidator) {
  "use strict";

  // input validation with an allowlist pattern
  function isValidOrderId(id) {
    return /^[0-9]{10}$/.test(id);
  }

  // output encoding for a URL query
  const query = encodeURLParameters({ search: "notebook & <script>" });
  // "search=notebook%20..." - spaces, &, < and > are all percent-encoded

  // only allow links to known, safe destinations
  URLListValidator.add("https", "help.sap.com");
  const safe = URLListValidator.validate("https://help.sap.com/docs"); // true
});

sap.ui.define(["sap/ui/util/Storage"], function (Storage) {
  "use strict";

  const storage = new Storage(Storage.Type.local, "myApp");

  // fine: a UI preference
  storage.put("compactMode", true);

  // NEVER: tokens, passwords, or personal / business data
